    id: 'ragu_bolognese', name: 'Beef and Pork Ragu', local: 'Ragù alla bolognese', cuisine: 'Italian', code: 'IT',
    pic: 'pix/ragu_bolognese.svg', servings: 4, active: 35, total: 220, diff: 2, diffLabel: 'Easy enough',
