    have: ['Onion', 'Garlic', 'Turmeric', 'Cumin seeds'],
    keeps: true,
    keepTitle: 'Five days, and it is meant to be made ahead',
    keepBody: 'Saag is traditionally cooked in a large pot and eaten across several days, and the flavour rounds out after a night in the fridge. It thickens to a spoonable paste; add hot water and a small knob of ghee when you reheat. It freezes for three months in portions.',
    method: [
      { text: 'Wash the mustard greens, spinach and kale in a sink of cold water, lift them out, then do it again in fresh water. Strip the kale leaves off their stems and roughly chop everything.', m: 10, tip: 'Grit is the one fault you cannot cook out, and greens hold it in the crease of every leaf. Lift the leaves out of the water rather than pouring the water off them.' },
      { text: 'Greens into a large pot with 300 ml water, the chopped ginger, half the garlic, the slit chillies and a teaspoon of salt. Lid on, medium-low, 35 minutes, until everything has collapsed and the stems are soft.', m: 36 },
      { text: 'Mash with a potato masher, or pulse a stick blender three or four times only.', m: 3, tip: 'Blended smooth it goes slimy and tastes flat. The texture of chopped leaf is half of what people are eating this for.' },
      { text: 'Rain the polenta in while stirring, then cook 10 minutes on low, stirring often and scraping the base.', m: 11, tip: 'This is the job maize flour does in the original: it takes the raw bitterness off the mustard leaf and gives the saag body. It sticks and catches, so keep the spoon moving.' },
      { text: 'For the tadka, melt the ghee in a small pan. Cumin seeds until they crackle, then the sliced onion, 6 minutes to gold. The remaining garlic, 1 minute. Off the heat, stir in the Kashmiri chilli and turmeric.', m: 9, tip: 'Ground spice goes in off the heat because in ghee that hot it burns in about ten seconds, and burnt chilli turns the whole pot bitter.' },
      { text: 'Pour the tadka into the greens, add the garam masala, and cook 3 minutes more. Salt to taste. Warm flatbread alongside.', m: 5 },
    ],
