    id: 'egg_hoppers', name: 'Egg Hoppers', local: '\u0db6\u0dd2\u0dad\u0dca\u0dad\u0dbb \u0d86\u0db4\u0dca\u0db4', cuisine: 'Sri Lankan', code: 'LK',
