    have: ['Turmeric', 'Cumin seeds', 'Mustard seeds', 'Salt'],
    keeps: true,
    keepTitle: 'Three days, and it sets like a paste',
    keepBody: 'The squash carries on breaking down in the fridge until it is closer to puree than stew. Warm it through with a splash of water and it comes back to something spoonable. The coconut dulls after the second day, so it is at its best early.',
    method: [
      { text: 'Rinse the lentils, then simmer them in 500 ml of water with the turmeric for 15 minutes, until soft.', m: 17 },
      { text: 'While they cook, peel the squash and cut it into 3 cm cubes.', m: 8 },
      { text: 'Squash into the lentils with 200 ml more water and the salt. Simmer 12 minutes, until a knife goes in with no resistance at all.', m: 13, tip: 'Take it past firm. Kootu is meant to be half-collapsed, and squash with bite left in it reads here as undercooked.' },
      { text: 'Blend the desiccated coconut, cumin seeds and green chillies with 150 ml of warm water into a coarse, wet paste.', m: 4, tip: 'Warm water gets far more out of desiccated coconut than cold. It is bone dry and has to swell before the blades can do anything with it.' },
      { text: 'Stir the paste in and simmer 4 minutes on low. Keep it below a boil.', m: 5, tip: 'Hard boiling once the coconut is in makes the texture grainy, and there is no way back from that.' },
      { text: 'Heat the coconut oil in a small pan. Mustard seeds until they pop, then the urad dal until it is the colour of straw, then the dried red chillies and curry leaves. Pour it over and stir once.', m: 3 },
    ],
