    items: [
      I('650 g', 'Pork belly, skin on', 5.5, 'local'), I('40 g', 'Sugar', 0.05, 'model'),
      I('40 ml', 'Shaoxing wine', 0.22, 'euro'), I('30 g', 'Dark soy sauce', 0.2, 'euro'),
      I('20 g', 'Soy sauce', 0.1, 'euro'), I('30 g', 'Fresh ginger', 0.26, 'local'),
      I('60 g', 'Spring onions', 0.45, 'local'), I('3', 'Star anise', 0.14, 'euro'),
      I('1', 'Cinnamon stick', 0.09, 'euro'), I('3', 'Dried red chillies', 0.1, 'euro', 1),
      I('20 g', 'Vegetable oil', 0.03, 'model'), I('250 g', 'Long grain rice', 0.44, 'model'),
      I('200 g', 'Pak choi', 1.1, 'local'),
    ],
    have: ['Sugar', 'Soy sauce', 'Vegetable oil', 'Long grain rice'],
    keeps: true,
    keepTitle: 'Four days, and it is better on day two',
    keepBody: 'The fat sets white and solid over the top in the fridge, which looks alarming and is exactly right — lift most of it off if you want, or stir it back in when you reheat. The meat keeps taking on the braise overnight, so the second night is the good one. Reheat slowly with a splash of water; boiled hard, the cubes shred.',
    method: [
      { text: 'Cut the pork belly into 3 cm cubes, skin left on. Put them in a pan of cold water, bring to the boil, and simmer 3 minutes while a grey scum rises. Drain and rinse the cubes under the tap.', m: 12, tip: 'That scum is blood and protein. Left in, it makes the braise cloudy and gives it a faintly muddy taste that no amount of soy will cover.' },
      { text: 'Dry the cubes properly on a tea towel. Slice the ginger into coins, cut the spring onions into 5 cm lengths.', m: 5, tip: 'Wet pork will not colour, and it spits when it hits caramel.' },
      { text: 'Oil and sugar into a heavy pan over medium heat. Leave it alone, swirling occasionally, for 3 to 4 minutes until the sugar melts and turns the colour of weak tea.', m: 5, tip: 'One shade past amber it goes bitter, and there is no way back. Take it off early — the braise darkens it further anyway.' },
      { text: 'Pork in, and toss for 4 minutes until every cube is coated and lightly browned.', m: 4 },
      { text: 'Shaoxing wine in — it should hiss hard. Let it reduce for a minute, then add the dark soy, soy sauce, ginger, spring onions, star anise, cinnamon and the dried chillies if you want the heat.', m: 3 },
      { text: 'Hot water to just cover. Lid on, lowest heat, 75 minutes. Look at it twice in that time to check it is barely trembling rather than boiling.', m: 75, tip: 'A rolling boil tightens the meat and clouds the sauce. You want the surface moving in one place only.' },
      { text: 'Rice on now: 250 g rinsed, 460 ml water, lid on, 10 minutes low then 10 off the heat.', m: 21 },
      { text: 'Lid off the pork, heat up to medium-high, and reduce for 10 to 15 minutes until the sauce is a syrup that coats each cube. Stir often near the end — the sugar catches the second it goes thick.', m: 15, tip: 'If it does catch, stop stirring, tip the cubes into a clean pan and leave the burnt layer behind. Scraping it in makes the whole pot taste of ash.' },
      { text: 'Halve the pak choi lengthways and boil it 2 minutes in salted water. Fish the star anise, cinnamon and ginger out of the pork.', m: 4 },
      { text: 'Pork over rice, greens alongside, a spoon of the syrup over everything.', m: 2 },
    ],
