    have: ['Onion', 'Garlic', 'Vegetable oil', 'Chopped tomatoes', 'Dried oregano', 'Bay leaves'],
    keeps: true,
    keepTitle: 'Four days, and better on day two',
    keepBody: 'The chipotle keeps moving into the meat overnight, so the second night is the good one. Keep the chicken in its sauce or it dries out. Reheat in a pan with a splash of water rather than the microwave, which drives the fat out and leaves the shreds stringy.',
    method: [
      { text: 'Put the chicken thighs in a pan with the stock, one onion cut in half, the bay leaves and a teaspoon of salt. Bring to a bare simmer and cook 20 minutes, until a thigh pulls apart under two forks.', m: 22, tip: 'A rolling boil tightens thigh meat and it will not shred cleanly afterwards. You want the surface barely moving.' },
      { text: 'Lift the chicken out and leave it until you can handle it. Keep the poaching liquid and discard the boiled onion and the bay leaves.', m: 4 },
      { text: 'Slice the second onion thinly. Blend the chopped tomatoes with the chipotle paste, the garlic and the oregano.', m: 5 },
      { text: 'Heat the oil in a wide pan and cook the sliced onion over medium-high heat for 6 minutes, until soft and browned at the edges.', m: 7 },
      { text: 'Pour in the blended sauce and cook 8 minutes, stirring now and then, until it thickens and darkens to brick red.', m: 8, tip: 'Chipotle pastes vary in heat by a factor of three. Taste here, while you can still stretch the sauce with more tomato.' },
      { text: 'Shred the chicken with two forks and stir it in with 150 ml of the poaching liquid. Simmer 8 minutes until the sauce clings to the meat and no liquid pools when you push it aside.', m: 9 },
      { text: 'Warm the tortillas in a dry pan, 20 seconds a side, until they puff and blister. Stack them under a tea towel.', m: 5 },
      { text: 'Serve the tinga on the tortillas with the coriander, lime wedges, and avocado if you have it.', m: 3 },
    ],
