    have: ['Onion', 'Garlic', 'Vegetable oil', 'Chopped tomatoes', 'Ground cumin', 'Dried oregano'],
    keeps: true,
    keepTitle: 'Three days, and the tortillas give up',
    keepBody: 'The filling and the sauce are both better on day two; the rolled tortillas are not, because they keep drinking sauce until they are indistinguishable from it. Cover and reheat at 180C for 20 minutes rather than microwaving, which turns the edges to rubber. It freezes well if you freeze it before baking.',
    method: [
      { text: 'Heat the oven to 200C. Peel and dice the sweet potato into 1 cm cubes, chop the onion, crush the garlic.', m: 8 },
      { text: 'Heat 15 g of the oil in a wide pan. Onion in for 5 minutes, then the sweet potato, garlic and cumin. Cover and cook 10 minutes, stirring twice, until the sweet potato gives under a spoon.', m: 15, tip: 'The lid is doing the work here. Uncovered, the cubes brown on the outside and stay raw in the middle.' },
      { text: 'Drain and rinse the beans, add them with a splash of water, and crush about a third of them against the side of the pan. Salt it and take it off the heat.', m: 4, tip: 'Crushing some of the beans is what stops the filling sliding out of the tortilla as you roll it.' },
      { text: 'Blend the chopped tomatoes with the chipotle paste and the oregano. Warm the sauce in a small pan for 5 minutes with a pinch of salt.', m: 6 },
      { text: 'Brush the tortillas with the rest of the oil and warm them in a dry pan a few seconds a side, until pliable.', m: 5, tip: 'A cold corn tortilla splits down the middle when you roll it. Ten seconds of heat is the whole difference.' },
      { text: 'Spread a ladle of sauce over the base of a baking dish. Fill each tortilla with the bean mixture, roll it, and lay it seam down in the dish.', m: 8 },
      { text: 'Pour the rest of the sauce over, grate the cheddar on top, and bake 20 minutes until the cheese browns and the sauce bubbles at the edges.', m: 20 },
      { text: 'While it bakes, slice the red onion thinly and squeeze the lime over it with a pinch of salt. Scatter it over the finished dish with the coriander, and soured cream if you want it.', m: 5 },
    ],
