    have: ['Olive oil', 'Garlic', 'Ground cumin', 'Salt', 'Black pepper'],
    keeps: true,
    keepTitle: 'Three days, and a better lunch than dinner',
    keepBody: "The sliced chicken keeps well sitting in its own juices and is good cold in a wrap the next day. Store the tahini sauce in a separate jar, because it stiffens in the cold and wants another spoon of water. Warm fresh bread rather than reheating yesterday's, which turns to cardboard.",
    method: [
      { text: 'Mix the cumin, ground coriander, paprika, turmeric, cinnamon, salt and black pepper with the olive oil, the crushed garlic and the juice of half the lemon.', m: 6 },
      { text: 'Open the chicken thighs out flat, cut the thick parts down so each piece is an even depth, and turn them through the marinade. Leave 30 minutes on the counter, or overnight in the fridge.', m: 35, tip: 'Even thickness is what stops one end drying out while the other is still pink. Thirty minutes does most of the work and a night does the rest.' },
      { text: 'Heat a heavy frying pan or griddle until a drop of water skitters across it. Lay the thighs down in a single layer and leave them alone for 6 minutes.', m: 8, tip: 'Moving them early tears the crust off and leaves it in the pan. The meat lets go by itself once it is properly browned.' },
      { text: 'Turn them and give them 5 minutes more, until the thickest part is opaque through. Work in two batches rather than crowding the pan.', m: 7, tip: 'A crowded pan falls below searing heat and the chicken poaches in its own liquid, which comes out grey and slack.' },
      { text: 'Rest the chicken on a board for 5 minutes, then slice it across into thin strips and turn the strips through the juices on the board.', m: 7 },
      { text: 'Whisk the tahini with the juice of the other half of the lemon, a pinch of salt and 60 ml cold water. It will seize into a stiff paste, so keep adding water a spoon at a time until it loosens to the thickness of double cream.', m: 4, tip: 'The seizing is normal and alarming the first time you see it. Tahini takes up water in stages and always comes back if you keep going.' },
      { text: 'Slice the red onion thin and cut the tomatoes into rounds. Warm the flatbread in the dry pan.', m: 6 },
      { text: 'Build each one: bread, chicken, onion, tomato, gherkins, a heavy drizzle of tahini sauce, parsley over the top.', m: 4 },
    ],
