    have: ['Olive oil', 'Garlic', 'Salt', 'Black pepper'],
    keeps: false,
    keepTitle: 'The crust does not survive a night',
    keepBody: 'Fried potato goes leathery in the fridge and a hot oven only gets you halfway back; a microwave gets you a steamed potato with chilli on it. The tahini sauce keeps a week in a jar, which is the only part worth putting away.',
    method: [
      { text: 'Cut the potatoes into 2 cm cubes, skin on. Boil them in well-salted water for 6 minutes, until a knife goes in with some resistance left.', m: 12, tip: 'Parboiling cooks the inside before the outside browns. Put them in raw and they scorch at the edges while the middle stays hard.' },
      { text: 'Drain them and leave them in the colander for 5 minutes to steam dry.', m: 5, tip: 'Surface water is what stops a crust forming. A dry potato hits hot oil and browns; a wet one hisses, sticks and tears.' },
      { text: 'Drain and dry the chickpeas at the same time.', m: 2 },
      { text: 'Olive oil into a wide frying pan on high heat. Potatoes in one layer, then left alone for 5 minutes before the first turn. Fry 12 minutes in all, until gold and crusted on most sides.', m: 14 },
      { text: 'Chickpeas in for the last 4 minutes, along with the ground coriander, paprika, chilli powder and black pepper.', m: 4 },
      { text: 'Chop the garlic and the red chillies fine and the fresh coriander roughly. Garlic and chilli into the pan for 60 seconds only, off the heat if they look like colouring.', m: 3, tip: 'Garlic burns in under a minute at this temperature and turns acrid. It goes in at the end for its bite, not to be softened.' },
      { text: 'Salt, the juice of half the lemon and most of the coriander tossed through in the pan.', m: 2 },
      { text: 'Loosen the tahini with 3 tbsp cold water and the rest of the lemon until it pours, and spoon it over the potatoes with the last of the coriander.', m: 3, tip: 'It thickens before it thins, so add the water in small amounts and keep going. It turns from stiff paste to pourable sauce quite suddenly.' },
    ],
