    keepBody: 'Ugali sets hard within a couple of hours and reheats to rubber, so make it to eat now. The sukuma wiki keeps three days and is good cold. If you do have cold ugali, slice it thick and fry it in a dry pan the next morning, which is a different dish and a good one.',
